// src/config.ts
var MAP = {
  SIZE: 60,
  /** Width of the ring road along the map edge and of every main road (spec §14.1). */
  ROAD_WIDTH: 4,
  /** Width of a street in a real district. */
  STREET_WIDTH: 3,
  ALLEY_WIDTH: 2,
  /** Rectangles wider or taller than this get split by a main road. */
  BLOCK_MAX: 34,
  /** A split never leaves a block narrower than this. */
  BLOCK_MIN: 12,
  /** Blocks at least this long on one side may get an alley. */
  ALLEY_MIN_BLOCK: 10,
  ALLEY_CHANCE: 0.8,
  /** Buildings inside a block are cut into lots of at most this many cells per side. */
  LOT_MAX: 4,
  FLOORS_MIN: 1,
  FLOORS_MAX: 6
};
var SNAKE = {
  INITIAL_LENGTH: 4,
  /** Cells per second at the initial length. */
  SPEED_BASE: 5,
  SPEED_MAX: 10,
  /** Extra cells per second for every segment beyond the initial length. */
  SPEED_K: 0.05,
  INPUT_QUEUE: 2
};
var PEOPLE = {
  /** People on the street in normal play; eaten ones are replaced from the ring road. */
  COUNT: 30,
  /** One step every 500 ms = 2 cells per second, independent of the snake's speed. */
  STEP_MS: 500,
  /** People flee when the snake's head is this many steps away or closer. */
  FLEE_RADIUS: 5,
  /** People placed at the start are at least this many steps from the head. */
  SPAWN_MIN_DIST: 15,
  /** Replacements pick randomly among this many ring-road cells furthest from the head. */
  SPAWN_FAR_PICK: 10,
  /** Steps a replacement walks inward before it starts wandering. */
  ENTER_STEPS: 4,
  /** Chance per step that a wanderer turns at a junction even though it could go straight. */
  TURN_CHANCE: 0.25
};
var HUNGER = {
  GRACE_MS: 15e3,
  SHRINK_MS: 2e3
};
var RECORDING = {
  /** People are drawn this much bigger. */
  PERSON_SCALE: 2.5,
  /**
   * Camera distance from the head; CAMERA.DISTANCE in normal play. The frame is about 14 cells
   * tall whatever the window shape, so a 9:16 window or a 9:16 crop of a wide one look the same.
   */
  CAMERA_DISTANCE: 34,
  /** Faster than CAMERA.FOLLOW, so the head stays near the middle of a narrow frame. */
  FOLLOW: 12,
  /** The crowd is one person per this many walkable cells (normal play: PEOPLE.COUNT). */
  CELLS_PER_PERSON: 35,
  /** Length of the head bounce and the new tail segment's pop when eating. */
  POP_MS: 350,
  /** How long the "+1" floats up. */
  PLUS_MS: 900
};

// src/grid.ts
var Terrain = { BUILDING: 0, ROAD: 1, ALLEY: 2, STREET: 3 };
var DIRS = [0, 1, 2, 3];
var DX = [0, 1, 0, -1];
var DZ = [-1, 0, 1, 0];
var opposite = (dir) => (dir + 2) % 4;
var Grid = class {
  constructor(width, height) {
    this.width = width;
    this.height = height;
    this.cellCount = width * height;
    this.terrain = new Uint8Array(this.cellCount);
  }
  cellCount;
  terrain;
  index(x, z) {
    return z * this.width + x;
  }
  x(cell) {
    return cell % this.width;
  }
  z(cell) {
    return Math.floor(cell / this.width);
  }
  inside(x, z) {
    return x >= 0 && z >= 0 && x < this.width && z < this.height;
  }
  walkable(cell) {
    return this.terrain[cell] !== Terrain.BUILDING;
  }
  /** The cell one step away, or −1 past the map edge. */
  neighbor(cell, dir) {
    const x = this.x(cell) + DX[dir];
    const z = this.z(cell) + DZ[dir];
    return this.inside(x, z) ? this.index(x, z) : -1;
  }
  /** Direction from `from` to the adjacent cell `to`. */
  dirTo(from, to) {
    const dx = this.x(to) - this.x(from);
    const dz = this.z(to) - this.z(from);
    if (dx > 0) return 1;
    if (dx < 0) return 3;
    return dz > 0 ? 2 : 0;
  }
  /** Steps from the map edge, so 0 on the outermost ring. */
  edgeDistance(cell) {
    const x = this.x(cell);
    const z = this.z(cell);
    return Math.min(x, z, this.width - 1 - x, this.height - 1 - z);
  }
  /**
   * Breadth-first step counts from `sources` over walkable cells, skipping cells where
   * `blocked` is true. Unreached cells are −1. Sources are always distance 0.
   */
  distances(sources, blocked, out) {
    out.fill(-1);
    const queue = new Int32Array(this.cellCount);
    let head = 0;
    let tail = 0;
    for (const source of sources) {
      out[source] = 0;
      queue[tail++] = source;
    }
    while (head < tail) {
      const cell = queue[head++];
      for (const dir of DIRS) {
        const next = this.neighbor(cell, dir);
        if (next < 0 || out[next] >= 0 || !this.walkable(next) || blocked(next)) continue;
        out[next] = out[cell] + 1;
        queue[tail++] = next;
      }
    }
    return out;
  }
};

// src/entities/people.ts
var SHIRT_COLORS = 6;
var far = (distance) => distance < 0 ? 1e9 : distance;
var People = class {
  constructor(grid, entry, rng) {
    this.grid = grid;
    this.entry = entry;
    this.rng = rng;
    this.at = new Int16Array(grid.cellCount).fill(-1);
  }
  list = [];
  /** How many people the crowd is kept at; more in recording mode (spec §15.4). */
  target = PEOPLE.COUNT;
  /** Person id by cell, −1 where nobody stands. */
  at;
  nextId = 0;
  /** Walkable, and neither the snake nor another person is there. The snake is a wall (spec §5.2). */
  free(cell, snake) {
    return cell >= 0 && this.grid.walkable(cell) && !snake[cell] && this.at[cell] < 0;
  }
  openDirs(cell, snake) {
    return DIRS.filter((dir) => this.free(this.grid.neighbor(cell, dir), snake));
  }
  add(cell, dir, state) {
    const person = {
      id: this.nextId++,
      cell,
      previous: cell,
      dir,
      state,
      enterLeft: state === "entering" ? PEOPLE.ENTER_STEPS : 0,
      color: this.rng.int(0, SHIRT_COLORS - 1)
    };
    this.list.push(person);
    this.at[cell] = person.id;
    return person;
  }
  /** Scatter people away from the head until the crowd reaches `target` (spec §5.1). */
  populate(snake, distance) {
    const candidates = [];
    for (let cell = 0; cell < this.grid.cellCount; cell++) {
      if (this.free(cell, snake) && far(distance[cell]) >= PEOPLE.SPAWN_MIN_DIST) candidates.push(cell);
    }
    while (this.list.length < this.target && candidates.length > 0) {
      const cell = candidates.splice(this.rng.int(0, candidates.length - 1), 1)[0];
      const dirs = this.openDirs(cell, snake);
      this.add(cell, dirs.length > 0 ? this.rng.pick(dirs) : 0, "wandering");
    }
  }
  /** Bring in a replacement on the ring road, far from the head, walking inward (spec §5.1). */
  spawnReplacement(snake, distance) {
    const candidates = this.entry.filter((cell2) => this.free(cell2, snake));
    if (candidates.length === 0) return null;
    candidates.sort((a, b) => far(distance[b]) - far(distance[a]));
    const cell = this.rng.pick(candidates.slice(0, PEOPLE.SPAWN_FAR_PICK));
    return this.add(cell, this.inwardDir(cell), "entering");
  }
  inwardDir(cell) {
    let best = 0;
    let bestEdge = -1;
    for (const dir of DIRS) {
      const next = this.grid.neighbor(cell, dir);
      if (next < 0) continue;
      const edge = this.grid.edgeDistance(next);
      if (edge > bestEdge) {
        best = dir;
        bestEdge = edge;
      }
    }
    return best;
  }
  remove(id) {
    const index = this.list.findIndex((person2) => person2.id === id);
    if (index < 0) return null;
    const [person] = this.list.splice(index, 1);
    this.at[person.cell] = -1;
    return person;
  }
  /** Everyone takes one step. `distance` is the head's step count with the body as walls. */
  step(snake, distance) {
    for (const person of this.list) {
      person.previous = person.cell;
      const near = distance[person.cell] >= 0 && distance[person.cell] <= PEOPLE.FLEE_RADIUS;
      if (near) person.state = "fleeing";
      else if (person.state === "fleeing" || person.state === "trapped") person.state = "wandering";
      const dirs = this.openDirs(person.cell, snake);
      if (dirs.length === 0) {
        if (near) person.state = "trapped";
        continue;
      }
      let dir;
      switch (person.state) {
        case "fleeing":
          dir = this.fleeDir(person, dirs, distance);
          break;
        case "entering":
          dir = this.enterDir(person, dirs);
          if (--person.enterLeft <= 0) person.state = "wandering";
          break;
        default:
          dir = this.wanderDir(person, dirs);
      }
      if (dir === null) continue;
      const next = this.grid.neighbor(person.cell, dir);
      this.at[person.cell] = -1;
      this.at[next] = person.id;
      person.cell = next;
      person.dir = dir;
    }
  }
  /** Step to the open neighbour furthest from the head, or stay if nowhere is better. */
  fleeDir(person, dirs, distance) {
    let best = [];
    let bestDistance = far(distance[person.cell]);
    for (const dir of dirs) {
      const d = far(distance[this.grid.neighbor(person.cell, dir)]);
      if (d > bestDistance) {
        best = [dir];
        bestDistance = d;
      } else if (d === bestDistance) {
        best.push(dir);
      }
    }
    return best.length > 0 ? this.rng.pick(best) : null;
  }
  enterDir(person, dirs) {
    let best = dirs[0];
    let bestEdge = -1;
    for (const dir of dirs) {
      const edge = this.grid.edgeDistance(this.grid.neighbor(person.cell, dir));
      if (edge > bestEdge || edge === bestEdge && dir === person.dir) {
        best = dir;
        bestEdge = edge;
      }
    }
    return best;
  }
  /** Keep going straight, sometimes turning; only turn back at a dead stop. */
  wanderDir(person, dirs) {
    const back = opposite(person.dir);
    const ahead = dirs.includes(person.dir);
    const sideways = dirs.filter((dir) => dir !== person.dir && dir !== back);
    if (ahead && (sideways.length === 0 || !this.rng.chance(PEOPLE.TURN_CHANCE))) return person.dir;
    if (sideways.length > 0) return this.rng.pick(sideways);
    return ahead ? person.dir : back;
  }
};

// src/entities/snake.ts
var Snake = class {
  /** Head first. */
  cells = [];
  /** Where each segment was before the last tick, for drawing in between (spec §7.3). */
  previous = [];
  dir;
  /** Occupancy by cell: 1 where a segment (head included) is. */
  occupied;
  queue = [];
  constructor(grid, head, dir) {
    this.dir = dir;
    this.occupied = new Uint8Array(grid.cellCount);
    let cell = head;
    for (let i = 0; i < SNAKE.INITIAL_LENGTH; i++) {
      this.cells.push(cell);
      this.occupied[cell] = 1;
      cell = grid.neighbor(cell, opposite(dir));
    }
    this.previous = [...this.cells];
  }
  get head() {
    return this.cells[0];
  }
  get tail() {
    return this.cells[this.cells.length - 1];
  }
  get length() {
    return this.cells.length;
  }
  /** The direction the snake will be heading once every queued turn is used. */
  get plannedDir() {
    return this.queue.length > 0 ? this.queue[this.queue.length - 1] : this.dir;
  }
  /**
   * Queue a turn. Repeats and 180° reversals are judged against the last queued direction,
   * so two quick presses make a tight U-turn without biting the neck (spec §4.4).
   */
  enqueue(dir) {
    const last = this.plannedDir;
    if (dir === last || dir === opposite(last) || this.queue.length >= SNAKE.INPUT_QUEUE) return false;
    this.queue.push(dir);
    return true;
  }
  /** Take the next queued turn and return the cell the head is about to enter (−1 off the map). */
  turnAndLook(grid) {
    const next = this.queue.shift();
    if (next !== void 0) this.dir = next;
    return grid.neighbor(this.head, this.dir);
  }
  /** Whether moving into `cell` bites the body. The tail is fine unless it stays put to grow. */
  bites(cell, growing) {
    if (!this.occupied[cell]) return false;
    return growing || cell !== this.tail;
  }
  move(cell, grow) {
    const old = this.cells;
    const cells = [cell, ...old];
    if (!grow) this.occupied[cells.pop()] = 0;
    this.occupied[cell] = 1;
    this.cells = cells;
    this.previous = cells.map((current, index) => old[index] ?? current);
  }
  /** Drop the last segment (starving) and return its cell. */
  shrink() {
    const cell = this.cells.pop();
    this.previous.pop();
    this.occupied[cell] = 0;
    return cell;
  }
  /** Forget in-between positions, e.g. after a death freezes the snake. */
  settle() {
    this.previous = [...this.cells];
  }
};

// src/map/city.ts
var BUILDING_COLORS = 8;
function finishCity(id, grid, lots, alleys) {
  const entry = [];
  for (let cell = 0; cell < grid.cellCount; cell++) {
    if (grid.terrain[cell] === Terrain.ROAD && grid.edgeDistance(cell) < MAP.ROAD_WIDTH) entry.push(cell);
  }
  return { id, grid, lots, alleys, spawn: findSpawn(grid), entry };
}
function straightRun(grid, cell, dir) {
  let run = 0;
  for (let next = grid.neighbor(cell, dir); next >= 0 && grid.walkable(next); next = grid.neighbor(next, dir)) run++;
  return run;
}
function findSpawn(grid) {
  const centreX = (grid.width - 1) / 2;
  const centreZ = (grid.height - 1) / 2;
  const candidates = [];
  for (let cell = 0; cell < grid.cellCount; cell++) {
    if (grid.terrain[cell] === Terrain.ROAD) candidates.push(cell);
  }
  const offset = (cell) => Math.abs(grid.x(cell) - centreX) + Math.abs(grid.z(cell) - centreZ);
  candidates.sort((a, b) => offset(a) - offset(b));
  for (const cell of candidates) {
    let best = null;
    let bestRun = 0;
    for (const dir of [0, 1, 2, 3]) {
      const behind = (dir + 2) % 4;
      if (straightRun(grid, cell, behind) < SNAKE.INITIAL_LENGTH - 1) continue;
      const run = straightRun(grid, cell, dir);
      if (run > bestRun) {
        best = { cell, dir };
        bestRun = run;
      }
    }
    if (best && bestRun >= 3) return best;
  }
  throw new Error("No road cell can hold the initial snake.");
}

